/*
 * @interlace/ui — the full CSS contract, as Interlace's own apps use it.
 *
 *   @import "tailwindcss";
 *   @import "@interlace/ui/styles/index.css";
 *
 * base.css (brand, semantics, structure: additive, what every component
 * needs) plus layer 4, the opt-in page styling. In the registry this is the
 * `interlace-foundation` item. See base.css for the layer model.
 */

@layer interlace.bridge, interlace.brand, interlace.semantics;

@import "./base.css";

/* 4. Page. Each file styles the page on purpose; none is needed by a
 * component. */
@import "./page/fonts.css";
@import "./page/preflight.css";
@import "./page/fumadocs.css";
@import "./page/shiki.css";

/*
 * @interlace/ui — the Interlace typefaces, applied to the app's OWN font
 * utilities. Opt-in: shipped by `interlace-foundation`, never by
 * `interlace-base`.
 *
 * `font-sans` and `font-mono` are the host app's keys. Redeclaring them swaps
 * the typeface of every page that uses them, including pages that never
 * render an Interlace component, so it is a decision the adopter makes by
 * installing this file, not a side effect of adding a button.
 *
 * Fonts: families only. Inter / JetBrains Mono are loaded by the app (next/font
 * or @font-face with font-display: swap, per TYPOGRAPHY_PHILOSOPHY "no FOIT").
 * This file names the family stack; it does not ship font binaries.
 */

@theme {
  /* structure/type.css points `font-body` (and through it `font-heading`)
     at `font-sans`, so this one line sets the Interlace typeface for
     components and the app alike. */
  --font-sans:
    'Inter', 'Inter Variable', system-ui, -apple-system, BlinkMacSystemFont,
    'Segoe UI', sans-serif;
  /* The serif stack for the editorial look. Nothing reads it until an app
     opts in with `--font-heading: var(--font-serif)` (structure/type.css). */
  --font-serif:
    'Source Serif 4', 'Source Serif Pro', ui-serif, Georgia, Cambria,
    'Times New Roman', serif;
  --font-mono:
    'JetBrains Mono', 'JetBrains Mono Variable', 'SF Mono', Menlo, Consolas,
    'Liberation Mono', monospace;
}

/*
 * @interlace/ui — PAGE / preflight: the token-aware baseline that goes
 * beyond Tailwind's own preflight.
 *
 * Layer 4 of 4 (opt-in page styling; ships in `interlace-foundation`, never
 * in base). Every rule sits in Tailwind's `base` layer, right after
 * Tailwind's preflight and BELOW `components` and `utilities`. It used to
 * sit in a custom `interlace.preflight` layer, which Tailwind's layer
 * statement ranks ABOVE utilities: `img { height: auto }` beat a call-site
 * `h-10`, and `svg { display: block }` beat `inline`. A baseline must lose
 * to every class the page writes; in `base` it does. The reduced-motion and
 * forced-colors rules still win where they must, through `!important`.
 *
 * Why this file exists (the "more advanced than Tailwind preflight" the
 * Interlace DS owes its consumers):
 *   1. Tailwind's preflight resets margins / borders / box-sizing — necessary
 *      but VALUELESS without tokens. We layer on the token-aware defaults the
 *      brand depends on (selection color, focus ring, scrollbar tint,
 *      ::placeholder, Inter font-features, text-wrap balance on headings).
 *   2. It enforces DESIGN_PRINCIPLES at the document baseline — every page
 *      that imports the DS inherits the right type rendering, the right focus
 *      visibility (WCAG 2.2 SC 2.4.13), the right reduced-motion contract.
 *   3. It owns the per-component min-viewport contract: `data-min-viewport`
 *      sets a container so a primitive can warn (dev) when rendered below
 *      its declared minimum — see DESIGN_PRINCIPLES.md #14.
 *
 * Forbidden in this file: brand color values (those live in brand/);
 * component-specific styles (those live in the primitive's cva); JS coupling.
 * Allowed: token-referencing `var(--*)`, prefers-reduced-motion + prefers-color-scheme
 * queries, container-type declarations.
 */

/* ─────────────────────────────────────────────────────────────────
 * 1. Body + heading baseline
 *    Inter for prose/UI; JetBrains Mono inherited where set. font-feature-settings
 *    activates cv11 (single-storey a → matches our written language) + ss01
 *    (alternate g). text-rendering: optimizeLegibility on body only (not
 *    monospace — that's mechanical, not prose).
 * ──────────────────────────────────────────────────────────────── */
@layer base {
body {
  font-family: var(--font-body);
  font-feature-settings:
    'cv11',
    'ss01',
    'calt',
    'liga';
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background-color: var(--background);
  color: var(--foreground);
}

/* Headings get text-wrap: balance for two-line + better visual rhythm.
 * Browsers without support (older Safari/Firefox) gracefully fall back to
 * normal wrapping. */
h1,
h2,
h3,
h4,
h5,
h6 {
  text-wrap: balance;
}

/* Prose paragraphs get text-wrap: pretty (avoids orphan-word last lines).
 * Same graceful fallback contract. */
p {
  text-wrap: pretty;
}

/* Monospace inheritance — code/kbd/samp/pre use the DS mono token,
 * not the browser default (Courier). */
code,
kbd,
samp,
pre {
  font-family: var(--font-mono);
  font-feature-settings: 'calt';
}

/* ─────────────────────────────────────────────────────────────────
 * 2. Selection + focus contract
 *    Selection: brand accent at low alpha (legible on both light + dark
 *    surfaces). Focus-visible: 2px solid --ring, 2px offset (WCAG 2.2
 *    SC 2.4.13 — ≥3:1 contrast, ≥2px thick). NEVER outline: none without a
 *    replacement.
 * ──────────────────────────────────────────────────────────────── */
::selection {
  background-color: color-mix(in oklch, var(--ring) 24%, transparent);
  color: var(--foreground);
}

/* The DS focus ring contract — every interactive primitive inherits this
 * unless it explicitly opts out for a designed alternative. */
:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  border-radius: 2px;
}

/* No outline on click-only focus (mouse / touch users don't need it; SC 2.4.7
 * is satisfied by :focus-visible). */
:focus:not(:focus-visible) {
  outline: none;
}

/* ─────────────────────────────────────────────────────────────────
 * 3. Form-element inheritance
 *    Tailwind preflight already resets borders + appearance, but input/textarea/
 *    button still inherit Times/Helvetica on some browsers. Force the DS font.
 *    ::placeholder uses --muted-foreground for AA contrast on every surface.
 * ──────────────────────────────────────────────────────────────── */
input,
textarea,
select,
button {
  font-family: inherit;
  font-feature-settings: inherit;
}

::placeholder {
  color: var(--muted-foreground);
  opacity: 1; /* Firefox defaults to 0.54 — restore full opacity for AA. */
}

/* ─────────────────────────────────────────────────────────────────
 * 4. Image + media defaults
 *    Responsive by default (max-width: 100%). vertical-align: middle
 *    prevents the descender gap under inline images.
 *
 *    `height: auto` applies to PHOTOGRAPHIC media only (img/picture/
 *    video) — matching Tailwind's own preflight, which deliberately
 *    excludes svg + canvas. This layer is declared after `utilities`,
 *    so a blanket `svg { height: auto }` here would defeat `h-full` on
 *    every svg that carries a viewBox (the element snaps to the
 *    viewBox's intrinsic ratio instead of stretching): InterlaceWeave's
 *    square overlay spilling 180px past its card is how this was found.
 *    Drawn surfaces keep author-controlled sizing.
 * ──────────────────────────────────────────────────────────────── */
img,
picture,
video,
canvas,
svg {
  display: block;
  max-width: 100%;
  vertical-align: middle;
}

img,
picture,
video {
  height: auto;
}

/* ─────────────────────────────────────────────────────────────────
 * 5. Scrollbar tint
 *    A subtle DS-tinted scrollbar on long surfaces (modern browsers). Avoids
 *    the heavy OS-default look without going invisible. Webkit + standards
 *    syntax both included for coverage.
 * ──────────────────────────────────────────────────────────────── */
* {
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

*::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
*::-webkit-scrollbar-track {
  background: transparent;
}
*::-webkit-scrollbar-thumb {
  background-color: var(--border);
  border-radius: 9999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
*::-webkit-scrollbar-thumb:hover {
  background-color: var(--muted-foreground);
}

/* ─────────────────────────────────────────────────────────────────
 * 6. Motion contract
 *    Smooth-scroll on document navigation (anchor links, history nav).
 *    prefers-reduced-motion overrides EVERYTHING — including any animation
 *    a component sets — by clamping durations to 0.01ms (per WCAG SC 2.3.3
 *    + the Tailwind motion-safe philosophy). DESIGN_PRINCIPLES #7.
 * ──────────────────────────────────────────────────────────────── */
html {
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* View transitions (`document.startViewTransition`, React <ViewTransition>,
 * cross-document `@view-transition`). The browser's default crossfade is
 * retimed to the motion tokens, so a page swap moves like the rest of the
 * system; a site's own `::view-transition-*(name)` rules are more specific
 * and win. Under reduced motion every view-transition animation is removed:
 * the `*` clamp above does not match these pseudo-elements. They are global
 * rules, so they live here in the page layer, not in base.css. */
::view-transition-group(*) {
  animation-duration: var(--duration-medium);
  animation-timing-function: var(--ease-move);
}
::view-transition-old(*),
::view-transition-new(*) {
  animation-duration: var(--duration-medium);
}

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }
}

/* ─────────────────────────────────────────────────────────────────
 * 7. Tabular numerals for data
 *    Vertically-scanned number lists / tables / live-changing counters get
 *    tabular-nums + lining figures, so digits don't jump as the value
 *    updates. TYPOGRAPHY_PHILOSOPHY "Numerals".
 * ──────────────────────────────────────────────────────────────── */
table,
[role='grid'],
[data-tabular-nums] {
  font-variant-numeric: tabular-nums lining-nums;
}

/* ─────────────────────────────────────────────────────────────────
 * 8. Min-viewport contract — DESIGN_PRINCIPLES #14
 *    Each primitive declares the smallest viable viewport via the
 *    `data-min-viewport="<px>"` attribute on its root. preflight establishes
 *    the container so consumers (or a future preflight v2 with a
 *    `body[data-interlace-dev]` gate) can render a warning when a primitive
 *    is mounted in a container narrower than its declared minimum.
 *
 *    Today the attribute is documented machine-readable metadata (visible in
 *    devtools, queryable in E2E tests). The visual dev-mode warning is wired
 *    in apps that opt-in via `<body data-interlace-dev>`.
 * ──────────────────────────────────────────────────────────────── */
/*
 * ⚠️ The containment is GATED on the dev opt-in, and that gate is load-bearing.
 *
 * `container-type: inline-size` applies inline-axis SIZE CONTAINMENT, which
 * makes an element's intrinsic inline size exactly ZERO. Applied unconditionally
 * — as it was until 2026-08-10 — every primitive that declares
 * `data-min-viewport` AND is shrink-to-fit (`inline-block`, `inline-flex`, or a
 * content-sized flex item) computed `width: 0px`, its children overflowed the
 * box, and the component rendered as a sliver or as one word per line.
 *
 * Measured on `ReadingTime`: 0px with the rule, 28.84px without it. It also
 * zeroed NumberField (154px), ToggleGroup (120px), PublishedDate (88px), the
 * Delta cell in MetricTable, and FocusRing — and it was live on
 * ds.interlace.tools, where these render as the public previews.
 *
 * The containment exists only so the `@container` queries below can fire. Those
 * queries are themselves gated on `body[data-interlace-dev]`, so outside dev
 * mode the containment bought nothing and cost this. Gating it matches the
 * queries it serves.
 *
 * Known limitation, accepted deliberately: inside the dev gate a shrink-to-fit
 * primitive still collapses, because there is no CSS selector for "block-level"
 * and containment is meaningless on an inline box. A dev-only visual artefact in
 * an opt-in debugging mode is a far better trade than a zero-width component in
 * production, which is what we had.
 */
body[data-interlace-dev] [data-min-viewport] {
  container-type: inline-size;
}

body[data-interlace-dev] [data-min-viewport='320'] {
  @container (max-width: 319px) {
    outline: 2px dashed color-mix(in oklch, var(--destructive) 70%, transparent);
    outline-offset: 4px;
    position: relative;
  }
}

body[data-interlace-dev] [data-min-viewport='480'] {
  @container (max-width: 479px) {
    outline: 2px dashed color-mix(in oklch, var(--destructive) 70%, transparent);
    outline-offset: 4px;
    position: relative;
  }
}

body[data-interlace-dev] [data-min-viewport='768'] {
  @container (max-width: 767px) {
    outline: 2px dashed color-mix(in oklch, var(--destructive) 70%, transparent);
    outline-offset: 4px;
    position: relative;
  }
}

/* ─────────────────────────────────────────────────────────────────
 * 9. forced-colors / high-contrast mode
 *    Windows High Contrast Mode + macOS Increased Contrast users need our
 *    focus ring to remain visible. Defer color values to system tokens in
 *    forced-colors so user overrides win — DESIGN_PRINCIPLES #9.
 * ──────────────────────────────────────────────────────────────── */
@media (forced-colors: active) {
  :focus-visible {
    outline-color: Highlight;
  }
}

} /* end @layer base */

/*
 * @interlace/ui — PAGE / fumadocs: running Interlace components inside a
 * fumadocs docs site.
 *
 * Layer 4 of 4 (opt-in page styling). Import AFTER fumadocs' own CSS:
 *
 *   @import "fumadocs-ui/css/neutral.css";
 *   @import "fumadocs-ui/css/preset.css";
 *   @import "@interlace/ui/styles/page/fumadocs.css";
 *
 *   1. shadcn-token bridge — fumadocs ships `--color-fd-*` but not the bare
 *      shadcn names components are styled against (`bg-card`, `bg-popover`).
 *      These aliases fill them from fumadocs, so a docs site WITHOUT the
 *      Interlace brand still renders components in its own colours. When
 *      semantics.css is also loaded, its later layer wins, as intended.
 *   3. TOC visual fix — single-line indicator over the staircase rail.
 *   4. Remote-content styling — for @interlace/ui/fumadocs/remote-markdown.
 *
 * (2, the Shiki contrast boosts, is page/shiki.css. 5, the entry
 * animations, is structure/motion.css. The numbering is kept so older
 * references still land.)
 */

/* ─────────────────────────────────────────────────────────────────
 * 1. shadcn-token bridge — maps shadcn-bare tokens to fumadocs sources.
 *    Light + dark inherit from `--color-fd-*` which the app overrides.
 *
 *    Wrapped in `@layer interlace.bridge` so the cascade story is
 *    deterministic: `interlace.brand` and `interlace.semantics` (later
 *    layers, declared in base.css) override these bridge defaults
 *    cleanly. Without the layer wrap, this unlayered `:root` block
 *    would TRUMP the layered semantic bindings per CSS Cascade Layers
 *    spec (unlayered > all custom layers).
 * ──────────────────────────────────────────────────────────────── */
@layer interlace.bridge {
:root {
  --background: var(--color-fd-background);
  --foreground: var(--color-fd-foreground);
  --card: var(--color-fd-card);
  --card-foreground: var(--color-fd-card-foreground);
  --popover: var(--color-fd-popover);
  --popover-foreground: var(--color-fd-popover-foreground);
  --muted: var(--color-fd-muted);
  --muted-foreground: var(--color-fd-muted-foreground);
  --accent: var(--color-fd-accent);
  --accent-foreground: var(--color-fd-accent-foreground);
  --secondary: var(--color-fd-secondary);
  --secondary-foreground: var(--color-fd-secondary-foreground);
  --border: var(--color-fd-border);
  --input: var(--color-fd-border);
  --ring: var(--color-fd-ring);
  --destructive: hsl(0, 72%, 38%);
  --destructive-foreground: hsl(0, 0%, 100%);

  /* Tailwind v4 @theme-side aliases so utilities like `bg-card`,
     `border-border` resolve. Same value as above. */
  --color-background: var(--color-fd-background);
  --color-foreground: var(--color-fd-foreground);
  --color-card: var(--color-fd-card);
  --color-card-foreground: var(--color-fd-card-foreground);
  --color-popover: var(--color-fd-popover);
  --color-popover-foreground: var(--color-fd-popover-foreground);
  --color-muted: var(--color-fd-muted);
  --color-muted-foreground: var(--color-fd-muted-foreground);
  --color-accent: var(--color-fd-accent);
  --color-accent-foreground: var(--color-fd-accent-foreground);
  --color-secondary: var(--color-fd-secondary);
  --color-secondary-foreground: var(--color-fd-secondary-foreground);
  --color-border: var(--color-fd-border);
  --color-input: var(--color-fd-border);
  --color-ring: var(--color-fd-ring);
  --color-primary: var(--color-fd-primary);
  --color-primary-foreground: var(--color-fd-primary-foreground);
  --color-destructive: hsl(0, 72%, 38%);
  --color-destructive-foreground: hsl(0, 0%, 100%);

  /* shadcn chart palette — five distinct hues, led by the brand orange and green.
     Light-mode values pass ≥4.5:1 contrast on `bg-card` (white).
     Used by @/components/ui/chart `<ChartContainer>` + ChartConfig. */
  --chart-1: oklch(0.55 0.16 41);
  --chart-2: oklch(0.55 0.14 162);
  --chart-3: oklch(0.55 0.18 264);
  --chart-4: oklch(0.55 0.14 90);
  --chart-5: oklch(0.55 0.13 200);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

.dark {
  /* Dark-mode chart palette — lifted lightness so each series stays
     ≥4.5:1 on `bg-card` (near-black). */
  --chart-1: oklch(0.78 0.14 41);
  --chart-2: oklch(0.78 0.12 162);
  --chart-3: oklch(0.78 0.16 264);
  --chart-4: oklch(0.78 0.12 90);
  --chart-5: oklch(0.78 0.11 200);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}
} /* end @layer interlace.bridge */

/* ─────────────────────────────────────────────────────────────────
 * 3. Fumadocs TOC visual fix — clean single-line indicator over the
 *    staircase rail. The arbitrary-property utilities below are
 *    classes Tailwind v4 cannot generate from `text-(--fd-…)` shorthand.
 * ──────────────────────────────────────────────────────────────── */
/* In Tailwind's `utilities` layer, not unlayered: these override
 * fumadocs' own utility classes, which they tie with on layer and beat on
 * specificity (an id or an extra attribute/element). Unlayered, they would
 * also beat every utility the host app writes. */
@layer utilities {
.h-\(--fd-height\) {
  height: var(--fd-height);
}
.top-\(--fd-top\) {
  top: var(--fd-top);
}
.transition-\[top\,height\] {
  transition-property: top, height !important;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1) !important;
  transition-duration: 150ms !important;
}
#nd-toc .bg-fd-primary {
  transition-property: top, height !important;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1) !important;
  transition-duration: 150ms !important;
}

/* Hide gray rail segments and diagonal connectors — keep only the
   brand-tinted sliding indicator. */
#nd-toc .bg-fd-foreground\/10 {
  display: none !important;
}
#nd-toc svg line.stroke-fd-foreground\/10,
#nd-toc .stroke-fd-foreground\/10 {
  display: none !important;
}

/* Popover TOC item indentation by depth. */
[data-toc-popover-content] a {
  padding-inline-start: 14px !important;
}
[data-toc-popover-content] a[data-depth='3'] {
  padding-inline-start: 26px !important;
}
[data-toc-popover-content] a[data-depth='4'],
[data-toc-popover-content] a[data-depth='5'],
[data-toc-popover-content] a[data-depth='6'] {
  padding-inline-start: 36px !important;
}
} /* end @layer utilities */

@layer components {
  /* Responsive TOC visibility:
   *   xl+ (≥1280px): side TOC visible, popover TOC hidden
   *   <xl: popover TOC visible, side TOC hidden
   */
  @media (min-width: 1280px) {
    button[data-toc-popover-trigger],
    div[data-toc-popover-content] {
      display: none !important;
    }
  }
  @media (max-width: 1279px) {
    #nd-toc {
      display: none !important;
    }
  }
}

/* ─────────────────────────────────────────────────────────────────
 * 4. Remote-content styling — `<RemoteMarkdown>` (README / changelog /
 *    rule-doc) classes from @interlace/ui/fumadocs/remote-markdown.
 * ──────────────────────────────────────────────────────────────── */
/* Utilities layer for the same reason as section 3: fumadocs' `prose` is a
 * utility, and these must beat it inside remote content (they do, on
 * specificity) without outranking the host's own classes. */
@layer utilities {
.remote-readme a > img,
.remote-changelog a > img,
.remote-rule-doc a > img {
  display: inline-block !important;
  vertical-align: middle;
  height: auto;
}

.remote-readme div[align='center'],
.remote-changelog div[align='center'],
.remote-rule-doc div[align='center'] {
  text-align: center;
  display: flex !important;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 0.35rem;
  margin-bottom: 0.5rem;
}

.remote-readme div[align='center'] a,
.remote-changelog div[align='center'] a,
.remote-rule-doc div[align='center'] a {
  display: inline-flex !important;
  align-items: center;
}

.remote-readme img,
.remote-changelog img,
.remote-rule-doc img {
  max-width: 100%;
  height: auto;
}
} /* end @layer utilities */

/*
 * @interlace/ui — PAGE / shiki: AAA contrast for Shiki's GitHub themes.
 *
 * Layer 4 of 4 (opt-in page styling). Scoped to `.shiki span[style*=…]`,
 * so it touches nothing but Shiki output. Split out of the fumadocs file:
 * any app that renders Shiki wants it, docs framework or not.
 */

/* ─────────────────────────────────────────────────────────────────
 * 2. Shiki AAA boosts — github-light / github-dark themes.
 *    Boost muted comment + keyword colors past 7:1 contrast.
 *
 *    NOT in `@layer interlace.bridge` — these are component-style
 *    overrides keyed off inline Shiki styles. They need higher cascade
 *    weight than our bridge layer to actually win against the inline
 *    `style="--shiki-light: #..."` values; leaving them unlayered is
 *    intentional.
 * ──────────────────────────────────────────────────────────────── */
.shiki span[style*="--shiki-light:#6E7781"],
.shiki span[style*="--shiki-light:#6e7781"] {
  --shiki-light: #424952 !important;
}
.shiki span[style*="--shiki-light:#CF222E"],
.shiki span[style*="--shiki-light:#cf222e"] {
  --shiki-light: #82071e !important;
}
.shiki span[style*="--shiki-light:#0550AE"],
.shiki span[style*="--shiki-light:#0550ae"] {
  --shiki-light: #033d8b !important;
}
.shiki span[style*="--shiki-light:#953800"] {
  --shiki-light: #6c2700 !important;
}
.shiki span[style*="--shiki-light:#8250DF"],
.shiki span[style*="--shiki-light:#8250df"] {
  --shiki-light: #5a31aa !important;
}
.shiki span[style*="--shiki-light:#0A3069"] {
  --shiki-light: #062350 !important;
}

/* DynamicCodeBlock (install snippets, fumadocs) ships a different Shiki
   theme variant — match `--shiki-light: #XXXXXX` (with space) too. */
.shiki span[style*="#6F42C1"],
.shiki span[style*="#6f42c1"] {
  --shiki-light: #5a2da3 !important;
}
.shiki span[style*="#005CC5"],
.shiki span[style*="#005cc5"] {
  --shiki-light: #003e8a !important;
}
.shiki span[style*="#032F62"],
.shiki span[style*="#032f62"] {
  --shiki-light: #021f42 !important;
}
.shiki span[style*="#D73A49"],
.shiki span[style*="#d73a49"] {
  --shiki-light: #971923 !important;
}
.shiki span[style*="#24292E"],
.shiki span[style*="#24292e"] {
  --shiki-light: #14171b !important;
}

/* Dark-mode tokens — brighten muted colors over near-black bg. */
.shiki span[style*="#B392F0"],
.shiki span[style*="#b392f0"] {
  --shiki-dark: #d2b5ff !important;
}
.shiki span[style*="#9ECBFF"],
.shiki span[style*="#9ecbff"] {
  --shiki-dark: #c4e0ff !important;
}
.shiki span[style*="#F97583"],
.shiki span[style*="#f97583"] {
  --shiki-dark: #ffa3ad !important;
}
.shiki span[style*="--shiki-dark:#8B949E"],
.shiki span[style*="--shiki-dark:#8b949e"] {
  --shiki-dark: #b8c0c8 !important;
}
.shiki span[style*="--shiki-dark:#FF7B72"],
.shiki span[style*="--shiki-dark:#ff7b72"] {
  --shiki-dark: #ffa39d !important;
}
.shiki span[style*="--shiki-dark:#FFA657"],
.shiki span[style*="--shiki-dark:#ffa657"] {
  --shiki-dark: #ffc787 !important;
}
.shiki span[style*="--shiki-dark:#79C0FF"],
.shiki span[style*="--shiki-dark:#79c0ff"] {
  --shiki-dark: #a5d6ff !important;
}
